from urllib.parse import urlsplit, urlunsplit


def apply_rewrite_rules(rules, urls):
    """
    rules: 順序付きの辞書リスト
    urls: URL文字列のリスト

    戻り値:
        書き換え後のURL、または block に該当した場合は None
    """

    def host_matches(host, match_value):
        if host is None:
            return False

        host = host.lower()
        match_value = match_value.lower()

        if match_value.startswith("*."):
            # ドメインそのものは除外し、厳密なサブドメインだけを許可する
            base = match_value[2:]
            return host.endswith("." + base) and host != base

        return host == match_value

    def replace_host(parsed, new_host):
        """
        ホストだけを置き換え、ユーザー情報とポートは維持する。
        """
        netloc = parsed.netloc

        # user:password@host:port の userinfo 部分
        if "@" in netloc:
            userinfo, hostport = netloc.rsplit("@", 1)
            prefix = userinfo + "@"
        else:
            hostport = netloc
            prefix = ""

        # 既存ポートをそのまま取り出す
        port = ""
        if hostport.startswith("["):
            # IPv6 の場合
            close_bracket = hostport.find("]")
            if close_bracket != -1:
                port = hostport[close_bracket + 1:]
        elif hostport.count(":") == 1:
            # 通常の hostname:port
            port = hostport[hostport.rfind(":"):]

        # IPv6 アドレスを action_value に指定した場合に備える
        if ":" in new_host and not new_host.startswith("["):
            new_host = f"[{new_host}]"

        new_netloc = prefix + new_host + port

        return parsed._replace(netloc=new_netloc)

    result = []

    for url in urls:
        parsed = urlsplit(url)
        rewritten = parsed
        matched = False

        for rule in rules:
            match_type = rule["match_type"]
            match_value = rule["match_value"]
            action = rule["action"]

            if match_type == "path_prefix":
                is_match = parsed.path.startswith(match_value)

            elif match_type == "host":
                is_match = host_matches(parsed.hostname, match_value)

            elif match_type == "query_param":
                # 空の値もパラメータとして扱う
                query_names = {
                    name
                    for name, _ in __import__("urllib.parse", fromlist=["parse_qsl"])
                    .parse_qsl(parsed.query, keep_blank_values=True)
                }
                is_match = match_value in query_names

            else:
                raise ValueError(f"Unknown match_type: {match_type}")

            if not is_match:
                continue

            matched = True

            if action == "block":
                rewritten = None

            elif action == "strip_prefix":
                action_value = rule["action_value"]
                new_path = parsed.path

                if new_path.startswith(action_value):
                    new_path = new_path[len(action_value):]

                if new_path == "":
                    new_path = "/"

                rewritten = parsed._replace(path=new_path)

            elif action == "redirect_host":
                rewritten = replace_host(
                    parsed,
                    rule["action_value"],
                )

            elif action == "add_query_param":
                action_value = rule["action_value"]
                new_query = parsed.query

                if new_query:
                    new_query += "&" + action_value
                else:
                    new_query = action_value

                rewritten = parsed._replace(query=new_query)

            else:
                raise ValueError(f"Unknown action: {action}")

            # 最初に適合したルールだけを使用する
            break

        if rewritten is None:
            result.append(None)
        elif matched:
            result.append(urlunsplit(rewritten))
        else:
            # どのルールにも適合しない場合は元のURLをそのまま返す
            result.append(url)

    return result
